// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(address caller, uint256 newMin) public {
        vm.assume(caller != address(0));

        vm.prank(caller);
        bool okBefore;
        try c.SetMinSum(newMin) { okBefore = true; } catch { okBefore = false; }

        assertTrue(okBefore);
        assertTrue(c.MinSum() == newMin);

        vm.prank(caller);
        c.Initialized();

        vm.prank(caller);
        bool okAfter;
        try c.SetMinSum(newMin + 1) { okAfter = true; } catch { okAfter = false; }

        assertTrue(!okAfter);
    }
}
